import { Color, MeshStandardMaterial, type WebGLProgramParametersWithUniforms } from 'three'
import { color, scene as sceneTokens } from '@/tokens'
import {
  dieEmissiveGLSL,
  dieMetalnessGLSL,
  dieRoughnessGLSL,
  dieSurfaceGLSL,
  dieUniformsGLSL,
} from './shaders/die.glsl'

export interface DieParams {
  seed?: number
  blocks?: number
  cellScale?: number
  centerScale?: number
  lite?: boolean
  hum?: number
  accent?: string
  accentHi?: string
}

/**
 * A MeshStandardMaterial whose albedo / roughness / metalness / emissive are
 * generated by the procedural die shader. Keeps full PBR + env reflections.
 */
export class DieMaterial extends MeshStandardMaterial {
  readonly uniforms = {
    uProgress: { value: 0 },
    uTime: { value: 0 },
    uSeed: { value: 0 },
    uBlocks: { value: 5 },
    uCellScale: { value: 170 },
    uCenterScale: { value: 36 },
    uLite: { value: 0 },
    uHum: { value: 1 },
    uPowerStart: { value: sceneTokens.powerStart },
    uPowerFull: { value: sceneTokens.powerFull },
    uAccent: { value: new Color(color.accent) },
    uAccentHi: { value: new Color(color.accentHi) },
    uAmber: { value: new Color(color.amber) },
    uCore: { value: new Color(color.core) },
    uMetal: { value: new Color(color.graphite) },
    uMetalHi: { value: new Color(color.silver) },
  }

  constructor(params: DieParams = {}) {
    super({
      color: color.graphite,
      roughness: 0.5,
      metalness: 0.85,
      emissive: '#000000',
      emissiveIntensity: 1,
      envMapIntensity: 1.3,
    })
    this.setParams(params)
    this.defines = { USE_UV: '' }
    this.customProgramCacheKey = () => 'preambl-die-v1'
    this.onBeforeCompile = (shader: WebGLProgramParametersWithUniforms) => {
      Object.assign(shader.uniforms, this.uniforms)
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', '#include <common>\n' + dieUniformsGLSL)
        .replace('#include <map_fragment>', dieSurfaceGLSL)
        .replace('#include <roughnessmap_fragment>', dieRoughnessGLSL)
        .replace('#include <metalnessmap_fragment>', dieMetalnessGLSL)
        .replace('#include <emissivemap_fragment>', dieEmissiveGLSL)
    }
  }

  setParams(p: DieParams) {
    const u = this.uniforms
    if (p.seed !== undefined) u.uSeed.value = p.seed
    if (p.blocks !== undefined) u.uBlocks.value = p.blocks
    if (p.cellScale !== undefined) u.uCellScale.value = p.cellScale
    if (p.centerScale !== undefined) u.uCenterScale.value = p.centerScale
    if (p.lite !== undefined) u.uLite.value = p.lite ? 1 : 0
    if (p.hum !== undefined) u.uHum.value = p.hum
    if (p.accent) u.uAccent.value.set(p.accent)
    if (p.accentHi) u.uAccentHi.value.set(p.accentHi)
  }
}
